insert into public.sat_question_bank(id,practice_test_id,subject,module,question_number,source_page,answer_page,correct_answer,accepted_answers,response_type,question_lines,explanation_lines,needs_visual,content_status,question_mode) values
('practice-test-8:rw1-13','practice-test-8','english','rw1',13,1,1,'A','["A"]'::jsonb,'multiple-choice','["The findings remained _______ until a second experiment could confirm them.","A) tentative","B) decisive","C) irrelevant","D) exhaustive"]'::jsonb,'["Tentative means not yet confirmed."]'::jsonb,false,'verified','text'),
('practice-test-8:rw1-14','practice-test-8','english','rw1',14,1,1,'B','["B"]'::jsonb,'multiple-choice','["Two independent measurements _______ the engineer''s conclusion.","A) obscured","B) corroborated","C) challenged","D) prevented"]'::jsonb,'["Corroborated means independently supported."]'::jsonb,false,'verified','text'),
('practice-test-8:rw1-15','practice-test-8','english','rw1',15,1,1,'C','["C"]'::jsonb,'multiple-choice','["The apparent trend was _______: new evidence showed no meaningful relationship.","A) robust","B) causal","C) spurious","D) consistent"]'::jsonb,'["Spurious describes an apparently meaningful but misleading relationship."]'::jsonb,false,'verified','text'),
('practice-test-8:rw1-16','practice-test-8','english','rw1',16,1,1,'B','["B"]'::jsonb,'multiple-choice','["The study''s conclusion was _______ because other explanations were not examined.","A) careful","B) premature","C) rigorous","D) unequivocal"]'::jsonb,'["Premature means reached before adequate evidence was considered."]'::jsonb,false,'verified','text'),
('practice-test-8:rw1-17','practice-test-8','english','rw1',17,1,1,'B','["B"]'::jsonb,'multiple-choice','["Choose the correct punctuation.","A) The bridge reopened, residents celebrated.","B) The bridge reopened; residents celebrated.","C) The bridge reopened; and residents celebrated.","D) The bridge reopened residents celebrated."]'::jsonb,'["Two independent clauses may be joined by a semicolon."]'::jsonb,false,'verified','text'),
('practice-test-8:rw1-18','practice-test-8','english','rw1',18,1,1,'B','["B"]'::jsonb,'multiple-choice','["Choose the correct sentence.","A) The result was surprising, however, the measurement was repeated.","B) The result was surprising; however, the measurement was repeated.","C) The result was surprising however; the measurement was repeated.","D) The result was surprising; however the measurement was repeated."]'::jsonb,'["Use a semicolon before however and comma after it."]'::jsonb,false,'verified','text'),
('practice-test-8:rw1-19','practice-test-8','english','rw1',19,1,1,'B','["B"]'::jsonb,'multiple-choice','["Choose the correct colon placement.","A) The box contained: three tools, a hammer, saw, and level.","B) The box contained three tools: a hammer, saw, and level.","C) The box contained three: tools, a hammer, saw, and level.","D) The box: contained three tools, a hammer, saw, and level."]'::jsonb,'["The colon follows a complete clause to introduce its list."]'::jsonb,false,'verified','text'),
('practice-test-8:rw1-20','practice-test-8','english','rw1',20,1,1,'A','["A"]'::jsonb,'multiple-choice','["North route riders increased from 45 to 63. South route riders increased from 60 to 72. Which gained more?","A) North, by 6 more","B) South, by 6 more","C) North, by 18 more","D) They tied"]'::jsonb,'["North gained 18 and South gained 12: difference 6."]'::jsonb,false,'verified','text'),
('practice-test-8:rw1-21','practice-test-8','english','rw1',21,1,1,'B','["B"]'::jsonb,'multiple-choice','["Support was 42 of 60 in A, 36 of 45 in B, and 45 of 75 in C. Which percentage is highest?","A) A","B) B","C) C","D) A and C tie"]'::jsonb,'["Rates are 70%, 80%, and 60%, respectively."]'::jsonb,false,'verified','text'),
('practice-test-8:rw1-22','practice-test-8','english','rw1',22,1,1,'A','["A"]'::jsonb,'multiple-choice','["A lab tested strengths: pine 220 N, oak 340 N, birch 280 N. Which statement is supported?","A) Oak exceeds birch by 60 N.","B) Pine exceeds oak by 120 N.","C) Birch exceeds pine by 40 N.","D) Oak equals birch."]'::jsonb,'["Oak supported 340 N and birch 280 N, a difference of 60 N."]'::jsonb,false,'verified','text'),
('practice-test-8:rw1-23','practice-test-8','english','rw1',23,1,1,'B','["B"]'::jsonb,'multiple-choice','["Students who voluntarily attended tutoring scored higher on average. Which conclusion follows?","A) Tutoring must cause higher scores.","B) Tutoring attendance is associated with higher scores.","C) Every tutored student scored higher.","D) No lower-scoring student attended."]'::jsonb,'["An observational comparison shows association, not proof of cause."]'::jsonb,false,'verified','text'),
('practice-test-8:rw1-24','practice-test-8','english','rw1',24,1,1,'B','["B"]'::jsonb,'multiple-choice','["A pond warmed as trees were removed, but unusually hot weather occurred too. What''s the main limitation?","A) Trees never matter.","B) Weather is a possible alternate explanation.","C) Temperature was never measured.","D) The pond actually cooled."]'::jsonb,'["The unusually hot weather may also account for warming."]'::jsonb,false,'verified','text'),
('practice-test-8:math1-13','practice-test-8','math','math1',13,1,1,'B','["B"]'::jsonb,'multiple-choice','["Simplify $x^8/x^3$ when $x\\ne0$.","A) $x^{11}$","B) $x^5$","C) $x^{24}$","D) $x^{8/3}$"]'::jsonb,'["Subtract exponents: 8−3=5."]'::jsonb,false,'verified','text'),
('practice-test-8:math1-14','practice-test-8','math','math1',14,1,1,'B','["B"]'::jsonb,'multiple-choice','["For $t>0$, simplify $(t^{2/3})^6$.","A) $t^3$","B) $t^4$","C) $t^8$","D) $t^{12}$"]'::jsonb,'["Multiply exponents: (2/3)×6=4."]'::jsonb,false,'verified','text'),
('practice-test-8:math1-15','practice-test-8','math','math1',15,1,1,'B','["B"]'::jsonb,'multiple-choice','["If $\\sqrt{3x+1}=7$, find $x$.","A) 14","B) 16","C) 18","D) 24"]'::jsonb,'["Square: 3x+1=49, so x=16."]'::jsonb,false,'verified','text'),
('practice-test-8:math1-16','practice-test-8','math','math1',16,1,1,'C','["C"]'::jsonb,'multiple-choice','["Simplify $\\sqrt{50}+\\sqrt{8}$.","A) $5\\sqrt2$","B) $6\\sqrt2$","C) $7\\sqrt2$","D) $\\sqrt{58}$"]'::jsonb,'["Simplifying each radical gives 5√2+2√2, which equals 7√2."]'::jsonb,false,'verified','text'),
('practice-test-8:math1-17','practice-test-8','math','math1',17,1,1,'B','["B"]'::jsonb,'multiple-choice','["A corresponding angle of a transversal across parallel lines is 68°. What is the matching angle?","A) 22°","B) 68°","C) 112°","D) 136°"]'::jsonb,'["Corresponding angles are congruent."]'::jsonb,false,'verified','text'),
('practice-test-8:math1-18','practice-test-8','math','math1',18,1,1,'B','["B"]'::jsonb,'multiple-choice','["Same-side interior angles between parallel lines are $(3x+20)°$ and $5x°$. Find $x$.","A) 15","B) 20","C) 25","D) 40"]'::jsonb,'["8x+20=180, so x=20."]'::jsonb,false,'verified','text'),
('practice-test-8:math1-19','practice-test-8','math','math1',19,1,1,'B','["B"]'::jsonb,'multiple-choice','["Adjacent angles on a straight line are $(2x+10)°$ and $(3x-5)°$. Find $x$.","A) 30","B) 35","C) 40","D) 45"]'::jsonb,'["Since the angles form a line, 5x+5=180, giving x=35."]'::jsonb,false,'verified','text'),
('practice-test-8:math1-20','practice-test-8','math','math1',20,1,1,'B','["B"]'::jsonb,'multiple-choice','["The line $y=3x+b$ passes through (2,11). Find $b$.","A) 3","B) 5","C) 7","D) 9"]'::jsonb,'["Substitution into y=3x+b gives 11=6+b, so b=5."]'::jsonb,false,'verified','text'),
('practice-test-8:math1-21','practice-test-8','math','math1',21,1,1,'C','["C"]'::jsonb,'multiple-choice','["When do $3x+2y=8$ and $6x+ky=16$ describe the same line?","A) $k=2$","B) $k=3$","C) $k=4$","D) $k=6$"]'::jsonb,'["Double the first equation to get k=4."]'::jsonb,false,'verified','text'),
('practice-test-8:math1-22','practice-test-8','math','math1',22,1,1,'B','["B"]'::jsonb,'multiple-choice','["The quadratic $x^2+kx+16=0$ has one real solution and $k<0$. Find $k$.","A) −16","B) −8","C) −4","D) 8"]'::jsonb,'["Discriminant k²−64=0, and k<0 gives −8."]'::jsonb,false,'verified','text'),
('practice-test-8:math1-23','practice-test-8','math','math1',23,1,1,'B','["B"]'::jsonb,'multiple-choice','["What is the radius of $(x+1)^2+(y-4)^2=81$?","A) 4","B) 9","C) 18","D) 81"]'::jsonb,'["The squared radius is 81, so radius 9."]'::jsonb,false,'verified','text'),
('practice-test-8:math1-24','practice-test-8','math','math1',24,1,1,'B','["B"]'::jsonb,'multiple-choice','["A circle radius has slope 4/3. What is the slope of its tangent?","A) 3/4","B) −3/4","C) 4/3","D) −4/3"]'::jsonb,'["Tangent and radius are perpendicular, so take the negative reciprocal."]'::jsonb,false,'verified','text') on conflict(id) do nothing;
